#!/usr/bin/env node
'use strict';

/**
 * DelishAfrica® V3.0.4 — one-shot PUBLICATION READINESS GATE.
 * READ-ONLY: never builds, deploys, submits, publishes, modifies stores, or reads secrets.
 * Requires Node 20+, EAS proof file produced by the preflight, and an HTTPS API.
 * Fails closed when a required API contract is missing or a device acceptance is unverified.
 *
 * Usage:
 *   node scripts/delishafrica_v304_publication_gate.cjs
 *
 * Required independently validated evidence (not auto-generated by this script):
 *   DA_V304_QA_ACCEPTANCE_FILE=/absolute/path/to/qa-acceptance.json
 *   DA_V304_EAS_PREFLIGHT_FILE=/absolute/path/to/HF44_PRODUCTION_AND_QA_PREFLIGHT.json
 *
 * Never set a QA acceptance flag to true without an actual, dated phone test.
 */
const fs=require('node:fs');
const path=require('node:path');

const root=path.resolve(__dirname,'..');
const API='https://api.delishafrica.me';
const baseName='DelishAfrica V3.0.4';
const report={
  project:baseName,
  at:new Date().toISOString(),
  mode:'READ_ONLY_NO_PUBLICATION',
  mandatoryChecks:[],
  physicalAcceptance:[],
  blockers:[],
};
const push=(name,ok,detail)=>{
  report.mandatoryChecks.push({name,pass:!!ok,detail});
  if(!ok) report.blockers.push(name+': '+detail);
};
function loadJSON(filename){
  if(!filename || !path.isAbsolute(filename))return null;
  try{return JSON.parse(fs.readFileSync(filename,'utf8'));}catch{return null;}
}
async function httpGate(name,method,route,expected){
  try{
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),12000);
    let res;
    try{
      res=await fetch(API+route,{
        method,redirect:'error',signal:controller.signal,
        ...(method==='POST'?{headers:{'content-type':'application/json'},body:'{}'}:{})
      });
    }finally{clearTimeout(timer);}
    push(name,res.status===expected,method+' '+route+' HTTP '+res.status+'; expected '+expected);
  }catch(e){push(name,false,method+' '+route+': request failed ('+String(e.name||'network')+')');}
}
(async()=>{
  const evidence=loadJSON(process.env.DA_V304_EAS_PREFLIGHT_FILE);
  const expectedNames=['client','merchant','courier'];
  const signatures=new Set();
  for(const app of expectedNames){
    for(const platform of ['android','ios']){
      for(const profile of ['production',platform==='android'?'ataraxie-closed':'ataraxie-ios-qa']){
        signatures.add(app+'|'+platform+'|'+profile);
      }
    }
  }
  const received=new Set((evidence?.results||[]).filter(x=>x.status==='PASS').map(x=>x.app+'|'+x.platform+'|'+x.profile));
  push('EAS 12 production+QA profiles',evidence?.status==='PASS' && [...signatures].every(x=>received.has(x)),
       evidence?.status==='PASS'?'Verified stored EAS profile evidence':'Missing or incomplete EAS preflight proof');

  await httpGate('PRODUCTION API health','GET','/api/health',200);
  await httpGate('PRODUCTION payments auth protection','POST','/api/v1/payments/create-intent',401);
  await httpGate('PRODUCTION courier GPS auth protection','POST','/api/v1/orders/location/publish',401);
  await httpGate('PRODUCTION mission route auth & existence','POST','/api/v1/routes/mission-preview',401);
  await httpGate('PRODUCTION authenticated Merchant membership','GET','/api/v1/merchant/membership/me',401);
  await httpGate('PRODUCTION OrchidPay / ATM read-only BFF','GET','/api/v1/integrations/orchidpay/read-model/me',401);

  const receipt=loadJSON(process.env.DA_V304_QA_ACCEPTANCE_FILE);
  for(const key of ['androidClient','androidMerchant','androidCourier','iosClient','iosMerchant','iosCourier','endToEndOrderTest','merchantServerAvailability','stripeTestLedgerReconciliation']){
    const v=receipt?.[key];
    const ok=v?.passed===true && typeof v?.at==='string' && !Number.isNaN(Date.parse(v.at)) && typeof v?.evidence==='string' && v.evidence.trim().length>15;
    report.physicalAcceptance.push({check:key,pass:!!ok});
    if(!ok) report.blockers.push('Missing physical/manual signed acceptance: '+key);
  }
  const safe=report.blockers.length===0;
  report.status=safe?'TECHNICAL_GATES_PASS_MANUAL_PUBLICATION_APPROVAL_STILL_REQUIRED':'HOLD';
  const outfile=process.env.DA_V304_GATE_OUTPUT;
  if(outfile && path.isAbsolute(outfile)){
    fs.writeFileSync(outfile,JSON.stringify(report,null,2)+'\n',{mode:0o600});
  }
  for(const c of report.mandatoryChecks)console.log((c.pass?'PASS':'HOLD')+' '+c.name+' — '+c.detail);
  console.log('PHYSICAL_ACCEPTANCE',report.physicalAcceptance.filter(x=>x.pass).length+'/'+report.physicalAcceptance.length);
  console.log('FINAL='+report.status+'; this gate never publishes');
  process.exitCode=safe?0:2;
})().catch(e=>{console.error('RELEASE_GATE_ERROR',e.message);process.exitCode=3;});
